int getConclusion(int v1, int v2, int v3) { return v1 + v2 - v3; } void mainFunction() { std::ofstream f("bill.txt", std::ios::app), f2("CarParkManagementSystem.txt", std::ios::app); int pwd = 123456789, g_pwd = 0, price = 0, ent = 0, qut = 0, cnt = 0, mode = 0; float t = 0.0; bool c01 = false; std::string pl = "XX XXX XX"; std::cout << "Car Park Management System\n"; while (true) { std::cout << "Enter Password for user-1.\n"; if (std::cin >> g_pwd && g_pwd == pwd) break; std::cout << "Invalid password. Please try again.\n"; } while (true) { std::cout << "Choose the system program mode. Type 1 for bill system, 2 for car park management system and 3 to quit.\n"; if (!(std::cin >> mode) || mode == 3) break; if (mode == 1) { std::cout << "Price for Cars stayed in the park:\n1 hour or less => free\n1-2 hours => 5 USD\n2-3 hours => 7 USD\n3-4 hours => 10 USD\n4-5 hours => 15 USD\nMore than 5 hours => 20 USD\n"; while (true) { std::cout << "Car no: 1. Please enter the plate text of vehicle.\n"; std::cin.ignore(); std::getline(std::cin, pl); std::cout << "Please enter the time vehicle stayed in the park. Use the format: X.XX\n"; std::cin >> t; price = (t < 1.0) ? 0 : (t < 2.0) ? 5 : (t < 3.0) ? 7 : (t < 4.0) ? 10 : (t < 5.0) ? 15 : 20; f << "Vehicle: " << pl << "\nPrice: " << price << "\n\n"; std::cout << "Do you want to continue the process? Type 1 for yes, 0 for no.\n"; std::cin >> c01; if (!c01) { std::cout << "Process ended.\nBill saved in the direct location of C++ program.\n"; break; } } } else if (mode == 2) { for (int i = 0; i < 7; i++) { for (int j = 0; j < 24; j++) { while (true) { std::cout << "Hour: " << j + 1 << ". Type the count of vehicles entered this hour.\n"; if (std::cin >> ent && ent <= 100 && ent >= 0) break; std::cout << "Invalid value. Please type again.\n"; } while (true) { std::cout << "Hour " << j + 1 << ". Type the count of vehicles quitted this hour.\n"; if (std::cin >> qut && qut <= 100 && qut >= 0) break; std::cout << "Invalid value. Please type again.\n"; } cnt = getConclusion(cnt, ent, qut); std::cout << "There are " << cnt << " cars inside the car park.\n"; f2 << "Hour: " << j + 1 << "\nVehicle Count: " << cnt << "\n\n"; if (cnt == 100) { std::cout << "Car Park is full.\n"; f2 << "Car park is full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; } else if (cnt >= 80) { std::cout << "Car park is almost full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; f2 << "Car park is almost full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; } else if (cnt >= 50) { std::cout << "Half of the car park is full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; f2 << "Half of the car park is full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; } else if (cnt >= 25) { std::cout << "Quarter of the car park is full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; f2 << "Quarter of the car park is full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; } else if (cnt < 25 && cnt > 0) { std::cout << "Less than the quarter of the car park is full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; f2 << "Less than the quarter of the car park is full. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; } else { std::cout << "Car park is empty.\n"; f2 << "Car park is empty. Day: " << i + 1 << ", Hour: " << j + 1 << "\n"; } } std::cout << "Day: " << i + 1 << ". Vehicles inside the car park: " << cnt << "\n"; f2 << "Day: " << i + 1 << "\nThere are " << cnt << " vehicles inside the car park.\n"; } std::cout << "Week ended. Vehicle count: " << cnt << ".\n"; f2 << "Week 1 ended. There are " << cnt << " vehicles inside the car park.\n"; } } f.close(); f2.close(); } int main() { mainFunction(); return 0; }
